  for(int i=1;i<Layout.Count;i++){int x=a.Left+(int)(a.Width*Layout.Edges[i]);using(var p=new Pen(Color.FromArgb(80,116,180),2))e.Graphics.DrawLine(p,x,a.Top+15,x,a.Bottom-15);}}
